Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/BitVec/BasicAux.lean"],{"text":"/-\nCopyright (c) 2024 Lean FRO, LLC. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Joe Hendrix, Wojciech Nawrocki, Leonardo de Moura, Mario Carneiro, Alex Keizer, Harun Khan, Abdalrhman M Mohamed\n-/\nmodule\n\nprelude\npublic import Init.Grind.Tactics\nimport Init.Data.Nat.Basic\n\npublic section\n\nset_option linter.missingDocs true\n\n/-!\nThis module exists to provide the very basic `BitVec` definitions required for\n`Init.Data.UInt.BasicAux`.\n-/\n\nnamespace BitVec\n\nsection Nat\n\ninstance instOfNat : OfNat (BitVec n) i where ofNat := .ofNat n i\n\n/-- Return the bound in terms of toNat. -/\ntheorem isLt (x : BitVec w) : x.toNat < 2^w := x.toFin.isLt\n\n/--\nConverts a natural number to a bitvector of width `w`, returning the largest representable value\nif the number is too large.\n\nReturns `2^w - 1` for natural numbers greater than or equal to `2^w`.\n-/\ndef ofNatClamp (w n : Nat) : BitVec w :=\n  if h : n < 2 ^ w then\n    BitVec.ofNatLT n h\n  else\n    BitVec.ofNatLT (2 ^ w - 1) (Nat.sub_lt (Nat.two_pow_pos w) Nat.one_pos)\n\nend Nat\n\nsection arithmetic\n\n/--\nAdds two bitvectors. This can be interpreted as either signed or unsigned addition modulo `2^n`.\nUsually accessed via the `+` operator.\n\nSMT-LIB name: `bvadd`.\n-/\n@[expose, implicit_reducible]\nprotected def add (x y : BitVec n) : BitVec n := .ofNat n (x.toNat + y.toNat)\ninstance : Add (BitVec n) := ⟨BitVec.add⟩\n\n/--\nSubtracts one bitvector from another. This can be interpreted as either signed or unsigned subtraction\nmodulo `2^n`. Usually accessed via the `-` operator.\n\n-/\n@[expose, implicit_reducible]\nprotected def sub (x y : BitVec n) : BitVec n := .ofNat n ((2^n - y.toNat) + x.toNat)\ninstance : Sub (BitVec n) := ⟨BitVec.sub⟩\n\nend arithmetic\n\nend BitVec\n","refs":[[24,9,24,18,"47fd27e3472d",true],[24,21,24,26,"27ab36052eff",false],[24,28,24,34,"56369828dde7",false],[24,46,24,51,"8371687c859a",false],[24,55,24,61,"fe30fb1f7d92",false],[27,8,27,12,"33b6c981a782",true],[27,18,27,24,"56369828dde7",false],[27,32,27,37,"45457e7ac530",false],[27,49,27,54,"f747f4a032d5",false],[27,55,27,59,"0cd84dc396de",false],[35,22,35,25,"1a9353d78c15",false],[35,29,35,35,"56369828dde7",false],[37,4,37,18,"34b9e7dfca3a",false],[39,4,39,18,"34b9e7dfca3a",false],[39,32,39,42,"cbd723a11601",false],[39,44,39,59,"76b065ec4a27",false],[52,14,52,17,"9a7606fbebd2",true],[52,25,52,31,"56369828dde7",false],[52,37,52,43,"56369828dde7",false],[52,49,52,55,"fe30fb1f7d92",false],[52,61,52,66,"45457e7ac530",false],[52,71,52,76,"45457e7ac530",false],[53,0,53,8,"f1d77bd0be6b",true],[53,11,53,14,"369f8d4c8855",false],[53,16,53,22,"56369828dde7",false],[53,30,53,40,"9a7606fbebd2",false],[61,25,61,31,"56369828dde7",false],[61,37,61,43,"56369828dde7",false],[61,49,61,55,"fe30fb1f7d92",false],[61,68,61,73,"45457e7ac530",false],[61,79,61,84,"45457e7ac530",false],[62,11,62,14,"798c8633652d",false],[62,16,62,22,"56369828dde7",false]]});
